def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]
    if n == 1:
        return 'D' if opp_last == 'D' else 'C'

    total_opp_def = 0
    opp_def5 = 0
    opp_def10 = 0
    for i in range(n):
        if history[i][1] == 'D':
            total_opp_def += 1
            if n - i <= 5:
                opp_def5 += 1
            if n - i <= 10:
                opp_def10 += 1

    if opp_def10 >= 7:
        return 'D' if rng.random() < 0.94 else 'C'
    if n >= 15 and total_opp_def * 5 > n * 2:
        return 'D' if rng.random() < 0.90 else 'C'

    if opp_last == 'C':
        if my_last == 'D':
            if total_opp_def == 0:
                return 'D'
            if opp_def10 == 0 and total_opp_def <= max(2, n // 15):
                return 'D' if rng.random() < 0.70 else 'C'
            if opp_def5 == 0 and total_opp_def <= max(3, n // 10):
                return 'D' if rng.random() < 0.25 else 'C'
            return 'C' if rng.random() < 0.75 else 'D'

        if total_opp_def == 0 and n >= 8:
            return 'D'
        if opp_def10 == 0 and total_opp_def <= max(1, n // 25) and n >= 30:
            return 'D' if rng.random() < 0.03 else 'C'
        return 'C'

    if my_last == 'D':
        if opp_def10 >= 5:
            return 'D' if rng.random() < 0.55 else 'C'
        return 'C' if rng.random() < 0.72 else 'D'

    if n >= 2:
        prev_my, prev_opp = history[-2]

        if prev_my == 'D':
            if opp_def10 >= 4:
                return 'D' if rng.random() < 0.55 else 'C'
            return 'C' if rng.random() < 0.80 else 'D'

        if prev_opp == 'D':
            if opp_def10 >= 3:
                return 'D' if rng.random() < 0.75 else 'C'
            return 'D' if rng.random() < 0.60 else 'C'

    if opp_def5 <= 1 and total_opp_def <= max(2, n // 8):
        return 'C' if rng.random() < 0.45 else 'D'

    return 'D' if rng.random() < 0.75 else 'C'
